"""Generate an importable ISTQB CT-AI question bank.
The bank uses 7 chapter-specific lenses over 34 distinct, domain-grounded cases.
Each case has a different learning point, scenario, and decision task; it is not
created by changing a number in a copied question.
"""
from pathlib import Path
from pprint import pprint

