# Build two different, level-appropriate questions from every concrete case.
QUESTION_BANK = {}
for chapter, (title, contexts) in CHAPTERS.items():
    k2, k3 = [], []
    for n, (case, base) in enumerate(zip(contexts, CASES), start=1):
        concept, domain, situation, focus = base
        k2.append({
            "id": f"C{chapter}-K2-{n:02d}", "level": "K2", "concept": concept,
            "domain": domain,
            "question": f"In {domain}, {case} Explain how this situation illustrates {concept}, and identify the key distinction or quality concern a tester should document.",
            "answer_focus": focus,
        })
        k3.append({
            "id": f"C{chapter}-K3-{n:02d}", "level": "K3", "concept": concept,
            "domain": domain,
            "question": f"You are testing the {domain} system described here: {case} Design a practical test or assurance decision for this case, justify the evidence needed, and state what action follows from a failure. Relate the decision to {concept}.",
            "answer_focus": focus,
        })
    QUESTION_BANK[chapter] = {"title": title, "K2": k2, "K3": k3}


def verify(bank):
    questions = [q["question"] for chapter in bank.values() for level in ("K2", "K3") for q in chapter[level]]
    unique = set(questions)
    print(f"Total questions generated: {len(questions)}")
    print(f"Number of unique questions: {len(unique)}")
    print(f"Number of duplicates: {len(questions) - len(unique)}")
    print("First 10 sample questions:")
    for i, question in enumerate(questions[:10], 1):
        print(f"{i}. {question}")
    assert len(questions) >= 468
    assert len(unique) == len(questions)
    assert all(set(chapter) >= {"title", "K2", "K3"} for chapter in bank.values())


if __name__ == "__main__":
    verify(QUESTION_BANK)
    # Write a plain importable dictionary module in addition to this generator.
    target = Path(__file__).with_name("question_bank.py")
    target.write_text("# Generated by generate_unique_questions.py\nQUESTION_BANK = " + repr(QUESTION_BANK) + "\n", encoding="utf-8")
    print(f"Importable dictionary saved to: {target}")
